SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (97::BIGINT, 'Buen profe, sabe bastante y demuestra mucho amor a la carrera. Pero, si usted es de primer ingreso tal vez va estar un poco perdido en su clase, ya que en el curso no hay examenes ni quices que lo obliguen a aprender la materia y por eso se vuelve un poco aburrido. Se pasa fácil, con los 2proyectos'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ce538d29be4929259b363aaa26ff2925691e3e75d5ed951addecffafb52333be'::TEXT, ARRAY[2733]::BIGINT[]),
    (97::BIGINT, 'Tiene mucha pasión por lo que enseña, califica un poco duro pero explica bien. Buen profe y persona. Siempre está atento al correo o teams'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'b962e6b812fe6cd583597378bcef6a43af1f5d5f67eec49bd734048d696daae4'::TEXT, ARRAY[2733]::BIGINT[]),
    (97::BIGINT, 'Si se pasa, pero califica bastante duro los informes. Si se guía con informes anteriores de otros profes, con él, no le van a servir, ya que los trabaja diferente.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, '8e73ef1181ee20ddb62e87dd3c02fa052a2064a1134b43694398a860e1d432c5'::TEXT, ARRAY[2755]::BIGINT[]),
    (97::BIGINT, 'Un profesor excelente. explica excelente, muy carismatico y amable.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'fe4247ce90923f9b2cda9828882cc8e99ca35f04635b3dd5fda4b253a192aa6e'::TEXT, ARRAY[2742]::BIGINT[]),
    (97::BIGINT, 'La materia y la clase son muy aburridas pero se nota que este es un tema que a él le interesa demasiado. Él va a dar la clase con la misma energía si hay 20 personas poniendole atención o 0 personas. Si uno tiene una duda de fijo se la atiende. Casi todos los trabajos son grupales.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2023-07-06T00:00:00+00:00'::TIMESTAMPTZ, '23070f5a5412845319ed5a8951e3dcd021ccd9c46adb89b035af6dbada795489'::TEXT, ARRAY[937]::BIGINT[]),
    (97::BIGINT, 'El profe es buena nota, sin embargo prepárese un buen café antes de ir a su clase teórica, ya que es muy aburrida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2023-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'abbc154cfc077d0f4e137e1babeff12e94b74b51a5f93cf878a1e46c9da525d1'::TEXT, ARRAY[2755, 938]::BIGINT[]),
    (97::BIGINT, 'Las clases son largas, pero en general es un buen profe, lo mas importante del curso es estar en un buen grupo de trabajo, ya que todos los informes y tareas se hacen en grupo, si tienen un buen grupo pasan muy facil'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '7469678a3730869f1c25de25695117a5b3509c236d66ee2acaa9c3ffbe565c1b'::TEXT, ARRAY[938]::BIGINT[]),
    (97::BIGINT, 'Es extremadamente aburrido pero es buen profe, todo es grupal entonces hay que buscarse un buen grupo desde el inicio, se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '75834e2af09eb623367d703343cbbb0fad559f0ea188ab74df2a4176f13bd562'::TEXT, ARRAY[937]::BIGINT[]),
    (97::BIGINT, 'Como tal es buen profe, pero el asunto es que la materia es un poco aburrida, para el proyecto hay que tener un buen grupo desde el inicio el cuál va a ser el mismo para examenes y tareas grupales. Los trabajos son largos pero nada fuera de lo común.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '58f855388bf387a8e3913b64c8b0a7b352b426839ac63583dab0a3139d0ce08f'::TEXT, ARRAY[937]::BIGINT[]),
    (97::BIGINT, 'Siento que la calificación que tiene es baja, pero es cierto que las clases teóricas son aburridas y largas. Califica normal los informes si usted sabe hacerlos, y es muy accesible para consultas. En general es un muy buen profe, pero si está buscando pasar sin esfuerzo no es la mejor opción.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'ee49d6b9520a4dfc67c4961938e5a1866288a13d8b91a841a3f7eee5ddfebe3f'::TEXT, ARRAY[938]::BIGINT[]),
    (97::BIGINT, 'Matricular con él es pasar el curso, es un buen profe y sabe bastante pero sus clases son demasiado aburridas ya que es mucha información pero eso no quita que es un buen profe, dele sin miedo.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '8c1476ef29985ba3762dee561f4e278cbfa1af180abf0f579074c85567ac6278'::TEXT, ARRAY[937]::BIGINT[]),
    (97::BIGINT, '(Semipresencial). El profe sabe mucho de los temas del curso y es un poco más entretenido que el teórico. Los informes son largos, tediosos y el profe califica un toque duro. Siempre responde dudas casi al instante por teams. Deja pocas evaluaciones.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '42118f5b3c2d7096cb2fdbfa3c277200d91ebacc99a300ac2f0d71ba3add690f'::TEXT, ARRAY[938]::BIGINT[]),
    (97::BIGINT, 'Las clases son largas y aburridas, pero es más que todo por la materia. Se esfuerza porque el estudiante aprenda y da buena retroalimentación. El curso en sí se pasa fácil'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2022-06-04T00:00:00+00:00'::TIMESTAMPTZ, '43481712d059152bc99f9ca755b9be3d1ff644931317615da6289ab497da1cf5'::TEXT, ARRAY[937]::BIGINT[]),
    (97::BIGINT, 'Demasiado aburrido, se nota que sabe mucho pero para un curso tan general como ciencias de los materiales aburre demasiado, clases largas, pero exámenes y tareas fáciles. Califica super suave, entonces solo hay que hacer un buen trabajo y de fijo tiene más de 80'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, '9114d10db22f7a6a553ef02aeb6ef4abf96129402f1f7d3f2e66816553c59130'::TEXT, ARRAY[1205]::BIGINT[]),
    (97::BIGINT, 'El profe no es muy bueno para explicar, son muy tediosas sus clases, tiene un gran conocimiento en ambas materias, se pasa relativamente fácil y para ayudar es muy atento.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos proyectos grupales']::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'bcd8dad6384b1ee5273be37c9ca72a968cebaa9040df95b25edcab2692b04acd'::TEXT, ARRAY[938, 937]::BIGINT[]),
    (97::BIGINT, 'En las clases explica lo necesario, y siempre ayudó con dudas en horario fuera de clases, no lo considero mal profe.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, '5bbb74fa06e60ca2912e59b6eafecc85d8874a2c66c04ca0b782a3fed4680446'::TEXT, ARRAY[938]::BIGINT[]),
    (97::BIGINT, 'Increíblemente aburrido, pero no hace falta ir a clases para pasar con una nota buena. Consiga un buen grupo de trabajo e investigue bien para las tareas y exámenes, se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2021-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'e32df33d47a7dd367b9ac3ffbf50c6cb63dccafc106a0242575bd1caef36dc18'::TEXT, ARRAY[937]::BIGINT[]),
    (97::BIGINT, 'Pasar el curso es muy fácil, los trabajos y exámenes son bastante sencillos de hacer (más que todo investigación). El mae sabe un pichazo de lo que habla pero se vuelve cansado porque habla muchísimo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-20T00:00:00+00:00'::TIMESTAMPTZ, 'b56de6fc9eec89044647efb84d10cd80b252af5d127282aab0d8ff7a4f87c7fe'::TEXT, ARRAY[1205]::BIGINT[]),
    (97::BIGINT, 'Se notá que el profesor sabe, pero se vuelve muy cansado cuando habla toda la clase sin parar; por ende cuesta prestar atención toda la clase. Los examenes son super fáciles y las instrucciones son claras. Todos es en grupo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '35a073e6a14abea1240dbac197d860c8ca278dbd7960982ba9b73802bbc18523'::TEXT, ARRAY[937]::BIGINT[]),
    (97::BIGINT, 'El mae se ve que sabe de lo que está hablando, el problema es cuando habla sin parar como por 3 horas. Aunque uno trate de ponerle atención, simplemente no se puede. En si para pasar es muy fácil, lo tedioso es que todo es en grupo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '5eb094fa20e5bd308b5ca0732e88c4d68216200f18d3646446d9adc3a65fe6c6'::TEXT, ARRAY[937]::BIGINT[]),
    (97::BIGINT, 'El profesor es muy aburrido, pero es buena gente. a veces se enreda solo, los quices son de dificultad media aunque un poco específicos.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, '73e222ec454f80d57511f1fc64b4a4c280bccdd0bfb1be05025578657219d675'::TEXT, ARRAY[2755]::BIGINT[]),
    (97::BIGINT, 'Califica justo. La clase es súper aburrida y da mucha materia. Es complicado con la entrega de trabajos: el proyecto final nos lo pidió en CD y algunas tareas en infogramas o afiches. Mejor ir a clases y basarse en el libro para estudiar.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '036b720b8f336451f9d24118aa92cb6f339b2df2d3bf9166b447a7628d9dc220'::TEXT, ARRAY[1205]::BIGINT[]),
    (97::BIGINT, 'El es aburrido pero si logra ponerle atención se le entiende. Ayuda mucho con dudas y si usted le pide práctica para examen le da, es pura vida con eso y trata de que uno no se aburra'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, '23b60f8215550557f38712b39ac0c47e66b68183a6e547d0ee0e13a66132b8c9'::TEXT, ARRAY[1205]::BIGINT[]),
    (97::BIGINT, 'El curso es un bostezo pero el profesor es un tipo agradable que al menos intenta que la gente no se duerma muy rápido.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '375cb75eb1152d56a130f5c11c678d1cb8920739866a4683a1130463c7a66a73'::TEXT, ARRAY[937]::BIGINT[]),
    (97::BIGINT, 'El profe es buena gente y los exámenes no son difíciles, además el proyecto es sencillo y lo revisa relativamente suave. Lo único es que la clase es bien aburrida y es un verdadero esfuerzo no dormirse.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'c2fc25e370f5e47e1cee56bf78d95e9e3b68e6740ce2789a172b81251585a488'::TEXT, ARRAY[937]::BIGINT[]),
    (97::BIGINT, 'El profe es super aburrido jaja, pero es buena nota. Hace quices masomenos, se ve que sabe, pero le cuesta transmitirlo'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '61308bf456cf2c0a26f619cea1db87f786f73e99f7962f7c3ed37abfdd1af72f'::TEXT, ARRAY[938]::BIGINT[]),
    (97::BIGINT, 'Las clases son muy aburridas y deja mucho trabajo grupal, intenta hacer la clase dinámica pero no lo logra'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'e25a4aa57529cb48f65a4d6ddebfec9d64d5814aaa3c3998c55bc3ba27ae2b8a'::TEXT, ARRAY[937]::BIGINT[]),
    (97::BIGINT, 'Súper intenso con todos los bretes (califica hasta ortografía), pero es bueno.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, '97608e189fb63dfc9a38ae22ec7d6de93d0fb34f7bdc6e2c56b9b12459763ddb'::TEXT, ARRAY[2824]::BIGINT[]),
    (97::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2016-12-31T00:00:00+00:00'::TIMESTAMPTZ, '6f02e50164ab97ac73bfc25a67024780c76c51bbf9c3efef6dd72bcbf258db9e'::TEXT, ARRAY[937]::BIGINT[]),
    (97::BIGINT, 'Clases largas, no tiene buena dicción para explicar, para los exámenes basarse más en el libro. Exámenes muy específicos para la gran cantidad de materia. Califica justo. Proyecto facil'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '0b84ea4f7026595d189f175956bb7cbb06b865c42148b0dcc2d213733b6c3c00'::TEXT, ARRAY[1205]::BIGINT[]),
    (97::BIGINT, 'El curso en sí es aburrido pero pasable con el profe; Los exámenes son relativamente fáciles, el proyecto también y califica justo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '0f4d8162920d9e3f6489f8a271cc613cacf03f800374ca370c163143d3777568'::TEXT, ARRAY[1205]::BIGINT[]),
    (97::BIGINT, 'Las clases son lo peor, pero deja exámenes para la casa, trabajos súper fáciles y todo el mundo pasa'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-10T00:00:00+00:00'::TIMESTAMPTZ, 'ca000b0bc1f659f997336f025a41a56aef2568faaf23672ff022646751f649f3'::TEXT, ARRAY[937]::BIGINT[]),
    (97::BIGINT, 'Sus clases son un bostezo, es medio cae mal pero califica suave'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-13T00:00:00+00:00'::TIMESTAMPTZ, '0ed58cad0fa9a1a240c848bddec973228fc3320e5b45223e216664648ed6ab8e'::TEXT, ARRAY[937]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
